const itemsCounts = {};
q2Raw.split(' | ').forEach(personChoice => {
    personChoice.split(', ').forEach(item => {
        const cleanedItem = item.trim();
        if (cleanedItem) {
            itemsCounts[cleanedItem] = (itemsCounts[cleanedItem] || 0) + 1;
        }
    });
});
const sortedItems = Object.entries(itemsCounts)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 10);

// Chart 1: Money
new Chart(document.getElementById('moneyChart'), {
    type: 'bar',
    data: {
        labels: Object.keys(q1Counts),
        datasets: [{
            label: 'จำนวนเสียง',
            data: Object.values(q1Counts),
            backgroundColor: ['#10b981', '#3b82f6', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899', '#06b6d4'],
            borderRadius: 8
        }]
    },
    options: {
        indexAxis: 'y',
        responsive: true,
        maintainAspectRatio: false,
        plugins: { legend: { display: false } }
    }
});

// Chart 2: Items (Updated with multiple colors)
new Chart(document.getElementById('itemsChart'), {
    type: 'bar',
    data: {
        labels: sortedItems.map(i => i[0]),
        datasets: [{
            label: 'จำนวนผู้เลือก',
            data: sortedItems.map(i => i[1]),
            // ส่งอาเรย์ของสีเข้าไปให้แต่ละแท่ง
            backgroundColor: [
                '#6366f1', '#8b5cf6', '#a855f7', '#d946ef', '#ec4899', 
                '#f43f5e', '#ef4444', '#f97316', '#f59e0b', '#eab308'
            ],
            borderRadius: 6
        }]
    },
    options: {
        indexAxis: 'y',
        responsive: true,
        maintainAspectRatio: false,
        plugins: { 
            legend: { display: false } 
        },
        scales: {
            x: {
                beginAtZero: true,
                grid: { display: false }
            },
            y: {
                grid: { display: false }
            }
        }
    }
});

// Table for Items
const tableBody = document.getElementById('itemsTableBody');
sortedItems.forEach((item, index) => {
    const row = `<tr>
        <td class="px-4 py-3 border-b text-slate-600 font-bold">${index + 1}</td>
        <td class="px-4 py-3 border-b text-slate-800 font-medium">${item[0]}</td>
        <td class="px-4 py-3 border-b text-slate-600 font-semibold">${item[1]} เสียง</td>
    </tr>`;
    tableBody.innerHTML += row;
});

// Chart 3: Agreement
new Chart(document.getElementById('agreementChart'), {
    type: 'doughnut',
    data: {
        labels: ['เห็นชอบ', 'ไม่เห็นชอบ'],
        datasets: [{
            data: [34, 3],
            backgroundColor: ['#2563eb', '#cbd5e1'],
            borderWidth: 0
        }]
    },
    options: {
        cutout: '70%',
        plugins: {
            legend: { position: 'bottom' }
        }
    }
});